# ========================================================================
# APLICAÇÃO SHINY PARA PROCESSAMENTO DE PDF DE PESQUISA DE PREÇO
# VERSÃO COM MODULARIZAÇÃO E BOTÃO DE DOWNLOAD ESTILIZADO
# ========================================================================

# --- 1. Carregar Todas as Bibliotecas Necessárias ---
library(shiny)
library(stringr)
library(dplyr)
library(tidyr)
library(openxlsx)
library(bslib)
library(base64enc)
library(shinyjs)
library(Cairo)


# --- AUMENTAR LIMITE DE UPLOAD PARA 100MB ---
options(shiny.maxRequestSize = 100 * 1024^2)

# =============================================================================
# FUNÇÕES GLOBAIS E DE UTILIDADE
# =============================================================================
parse_br_number <- function(s_vector) {
  if (is.null(s_vector)) return(NA_real_)
  s_vector[is.na(s_vector)] <- ""
  
  s_cleaned <- str_remove_all(s_vector, "[R$\\s]")
  has_comma <- str_detect(s_cleaned, ",")
  
  s_cleaned[has_comma] <- str_replace(
    str_remove_all(s_cleaned[has_comma], "\\."),
    ",", "."
  )
  
  no_comma <- !has_comma
  if(any(no_comma)) {
    num_dots <- str_count(s_cleaned[no_comma], "\\.")
    needs_dot_removal <- num_dots > 1
    if(any(needs_dot_removal)) {
      s_cleaned[no_comma][needs_dot_removal] <- str_remove_all(s_cleaned[no_comma][needs_dot_removal], "\\.")
    }
  }
  
  return(suppressWarnings(as.numeric(s_cleaned)))
}

format_currency_br <- function(x, accuracy = 0.01) {
  sapply(x, function(val) {
    if (is.na(val) || !is.numeric(val)) {
      return("N/A")
    }
    paste0("R$ ", format(round(val, 2), nsmall = 2, big.mark = ".", decimal.mark = ",", trim = TRUE, scientific = FALSE))
  })
}

get_pdf_text_pages <- function(local_path, webr_pages) {
  if (!is.null(webr_pages) && length(webr_pages) > 0) {
    return(webr_pages)
  }
  if (requireNamespace("pdftools", quietly = TRUE)) {
    return(pdftools::pdf_text(local_path))
  }
  stop("Nenhum mecanismo de leitura de PDF disponível.")
}


# ===================================================================================
# LÓGICA DE EXTRAÇÃO DE DADOS (COM SUPORTE AO INCISO V E FALLBACKS)
# ===================================================================================

# FUNÇÃO DE FALLBACK PARA ANEXOS
extract_anexo_fallback <- function(text_block) {
  anexo <- NA_character_
  
  if (str_detect(text_block, regex("Anexos", ignore_case = TRUE))) {
    text_after_keyword <- str_split(text_block, regex("Anexos", ignore_case = TRUE))[[1]]
    if (length(text_after_keyword) >= 2) {
      search_text <- text_after_keyword[2]
      anexos_found <- str_extract_all(search_text, "[\\w\\s\\d.,_-]+\\.(?i)(pdf|png|jpeg|jpg)")[[1]]
      if (length(anexos_found) > 0) {
        anexo <- paste(str_squish(anexos_found), collapse = "; ")
      }
    }
  }
  
  if (is.na(anexo)) {
    anexos_found <- str_extract_all(text_block, "\\d[.)][\\s\\w,._-]+?\\.(?i)(pdf|png|jpeg|jpg)")[[1]]
    if (length(anexos_found) > 0) {
      anexo <- paste(str_squish(anexos_found), collapse = "; ")
    }
  }
  
  if (!is.na(anexo)) {
    anexo <- str_remove_all(anexo, "\\s*\\d{1,2}:\\d{2}\\s*") %>% str_squish()
  }
  
  return(anexo)
}

# FUNÇÃO DE FALLBACK PARA URLS
extract_url_fallback <- function(text_block) {
  url_final <- NA_character_
  
  tryCatch({
    tokens <- str_extract_all(text_block, "\\S+")[[1]]
    url_component_pattern <- "^https?://|([[:alnum:]_./?&=#%+-]){15,}"
    url_parts <- str_subset(tokens, url_component_pattern)
    
    junk_words <- c("Anexos", "Informações", "Adicionais", "Cotação", "frete", "Orçamento")
    url_parts <- url_parts[!tolower(url_parts) %in% tolower(junk_words)]
    url_parts <- str_subset(url_parts, "\\.(?i)(pdf|png|jpe?g)$", negate = TRUE)
    
    if (length(url_parts) > 0) {
      reconstructed_url <- paste(url_parts, collapse = "")
      final_url_candidate <- str_remove_all(reconstructed_url, "\\d{2}\\.\\d{3}\\.\\d{3}/\\d{4}-\\d{2}")
      final_url_candidate <- str_remove(final_url_candidate, "-$")
      
      if (nchar(final_url_candidate) > 0 && str_starts(final_url_candidate, "http")) {
        url_final <- final_url_candidate
      }
    }
  }, error = function(e) {
    # Silencioso, retorna NA
  })
  
  return(url_final)
}

extract_format_AB <- function(all_lines, state_vars) {
  all_quotes_list <- list()
  
  line_start_regex <- "^\\s*(\\d+)\\s+(I|II|III|IV|V)\\s+(.*)$"
  processed_line_regex <- "^(?:(.*?)\\s+)?([\\d,]+)\\s*(.*)$"
  item_start_detector_regex <- "^\\s*[Ii]tem:?\\s+\\d+"
  
  quote_indices <- which(str_detect(all_lines, line_start_regex))
  header_indices <- which(str_detect(all_lines, "Nº\\s+Inciso\\s+Nome"))
  quote_indices <- setdiff(quote_indices, header_indices)
  
  for (i in quote_indices) {
    line <- all_lines[i]
    
    base_match <- str_match(line, line_start_regex)
    if(is.na(base_match[1,1])) next
    
    n_cotacao <- base_match[1, 2]
    inciso_val <- base_match[1, 3]
    rest_of_line <- str_squish(base_match[1, 4])
    
    preco_match <- str_match(rest_of_line, "(R\\$\\s*[\\d.,]+)")
    preco_unitario_str <- if (!is.na(preco_match[1,1])) preco_match[1,1] else NA_character_
    
    data_match <- str_match(rest_of_line, "([0-9]{2}/[0-9]{2}/[0-9]{4})")
    data_cotacao <- if (!is.na(data_match[1,1])) data_match[1,1] else NA_character_
    
    compone_match <- str_match(rest_of_line, "\\b(Sim|N.o|Não)\\b")
    compone <- if (!is.na(compone_match[1,1])) str_replace(compone_match[1,1], "N.o", "Não") else "Sim"
    
    linha_incompleta_flag <- is.na(preco_unitario_str) || is.na(data_cotacao)
    
    line_for_processing <- rest_of_line
    if (!is.na(preco_unitario_str)) line_for_processing <- str_remove(line_for_processing, fixed(preco_unitario_str))
    if (!is.na(data_cotacao)) line_for_processing <- str_remove(line_for_processing, fixed(data_cotacao))
    if (!is.na(compone_match[1,1])) line_for_processing <- str_remove(line_for_processing, paste0("\\b", compone_match[1,1], "\\b"))
    line_for_processing <- str_squish(line_for_processing)
    
    match_data <- str_match(line_for_processing, processed_line_regex)
    
    nome_na_linha <- ""
    quantidade <- ""
    unidade <- ""
    
    if (!is.na(match_data[1, 1])) {
      nome_na_linha <- str_trim(match_data[1, 2])
      quantidade <- match_data[1, 3]
      unidade <- str_trim(match_data[1, 4])
    }
    
    if (is.na(nome_na_linha)) nome_na_linha <- ""
    
    if (str_detect(str_trim(nome_na_linha), "^[\\d.,]+\\s+[A-Za-z]")) {
      nome_na_linha <- ""
    }
    
    if (is.na(unidade)) unidade <- ""
    if (!is.na(quantidade) && str_detect(quantidade, "\\.")) {
      unidade <- str_squish(paste(quantidade, unidade))
      quantidade <- ""
    }
    if (!is.na(unidade)) {
      unidade <- str_remove(unidade, "\\s*\\d{2,}\\.\\d{3,}.*")
      unidade <- str_remove(unidade, "\\s*/\\d{4,}.*")
      unidade <- str_remove_all(unidade, "\\s*\\d{1,2}/\\d{1,2}/\\d{1,4}\\s*")
      unidade <- str_squish(unidade)
    }
    
    nome_partes_superiores <- c()
    for (j in (i - 1):max(1, i - 5)) {
      prev_line <- all_lines[j]
      if (str_detect(prev_line, "Nº\\s+Inciso\\s+Nome") || str_detect(prev_line, line_start_regex) || str_detect(prev_line, "Id da Compra|Data da Cotação")) {
        break
      }
      nome_partes_superiores <- c(str_squish(prev_line), nome_partes_superiores)
    }
    
    nome_partes_inferiores <- c()
    stop_words_nome <- "Id da Compra|Data da Cotação|Fornecedor:|Esfera|Critério Julgamento Item|Endereço Eletrônico|Anexos|Contato|Informacões Adicionais|Validade"
    for (k in (i + 1):min(length(all_lines), i + 5)) {
      next_line <- all_lines[k]
      if (str_detect(next_line, stop_words_nome) || str_detect(next_line, "^\\s*Nº\\s+Inciso") || str_detect(next_line, line_start_regex) || str_detect(next_line, item_start_detector_regex)) {
        break
      }
      nome_partes_inferiores <- c(nome_partes_inferiores, str_squish(next_line))
    }
    nome_completo <- str_squish(paste(paste(nome_partes_superiores, collapse = " "), nome_na_linha, paste(nome_partes_inferiores, collapse = " "), collapse = " "))
    
    if (nchar(nome_completo) > 0 && !str_detect(nome_completo, regex("Compras\\s*\\.\\s*gov\\s*\\.\\s*br", ignore_case = TRUE))) {
      nome_completo <- paste(nome_completo, "- Compras.gov.br")
    }
    nome_completo <- str_remove(nome_completo, "^-") %>% str_squish()
    
    preco_numerico <- parse_br_number(preco_unitario_str)
    
    preco_formatado <- if (!is.na(preco_numerico)) {
      str_replace(sprintf("%.2f", preco_numerico), "\\.", ",")
    } else {
      preco_unitario_str
    }
    
    endereco_eletronico <- NA_character_
    anexo <- NA_character_
    
    next_quote_line_idx <- length(all_lines) + 1
    if (i < length(all_lines)) {
      following_quotes <- which(str_detect(all_lines[(i + 1):length(all_lines)], line_start_regex))
      if (length(following_quotes) > 0) {
        next_quote_line_idx <- i + following_quotes[1]
      }
    }
    
    cotacao_uasg <- NA_character_
    if (!inciso_val %in% c("III", "IV", "V")) {
      search_lines_uasg <- all_lines[i:(next_quote_line_idx - 1)]
      uasg_header_line_idx <- which(str_detect(search_lines_uasg, "Esfera") & str_detect(search_lines_uasg, "UASG"))
      if (length(uasg_header_line_idx) > 0) {
        idx_in_window <- uasg_header_line_idx[1]
        if (idx_in_window + 1 <= length(search_lines_uasg)) {
          next_line <- search_lines_uasg[idx_in_window + 1]
          uasg_match <- str_match(next_line, "(\\d{5,6})")
          if (!is.na(uasg_match[1, 2])) {
            cotacao_uasg <- uasg_match[1, 2]
          }
        }
      }
      if (is.na(cotacao_uasg)) {
        search_block_text <- paste(search_lines_uasg, collapse = " ")
        uasg_fallback_match <- str_match(search_block_text, "UASG\\s*:?\\s*(\\d{5,6})")
        if (!is.na(uasg_fallback_match[1, 2])) {
          cotacao_uasg <- uasg_fallback_match[1, 2]
        }
      }
    }
    
    search_window_start <- i + 1
    search_window_end <- min(next_quote_line_idx - 1, length(all_lines))
    
    if (search_window_start <= search_window_end) {
      quote_lines <- all_lines[search_window_start:search_window_end]
      full_quote_text <- paste(quote_lines, collapse = " ")
      
      if (inciso_val %in% c("III", "IV", "V")) {
        tokens <- str_extract_all(full_quote_text, "\\S+")[[1]]
        url_component_pattern <- "^https?://|\\?|&|=|[-A-Za-z0-9_.]{20,}"
        url_parts <- str_subset(tokens, url_component_pattern)
        url_parts <- str_subset(url_parts, "produto|frete", negate = TRUE)
        if (length(url_parts) > 0) {
          endereco_eletronico <- paste(url_parts, collapse = "")
        }
        
        is_original_url_valid <- !is.na(endereco_eletronico) && str_starts(str_trim(endereco_eletronico), "http")
        
        if (!is_original_url_valid) {
          endereco_eletronico <- extract_url_fallback(full_quote_text)
        }
        
        start_anexo_idx <- head(str_which(tokens, "^\\d+\\.$"), 1)
        end_anexo_idx <- head(str_which(tokens, "\\.(?i)(pdf|png|jpe?g)$"), 1)
        if (length(start_anexo_idx) > 0 && length(end_anexo_idx) > 0 && start_anexo_idx < end_anexo_idx) {
          dirty_anexo_tokens <- tokens[start_anexo_idx:end_anexo_idx]
          clean_anexo_tokens <- setdiff(dirty_anexo_tokens, url_parts)
          anexo <- paste(clean_anexo_tokens, collapse = " ")
        }
        
        if (is.na(anexo) || anexo == "") {
          anexo <- extract_anexo_fallback(full_quote_text)
        }
        
      } else {
        anexo_match <- str_match(full_quote_text, "([\\w\\s.-]+\\.(?i)(pdf|png|jpeg|jpg))")
        if (!is.na(anexo_match[1, 1])) { anexo <- str_squish(anexo_match[1, 1]) }
        url_match <- str_match(full_quote_text, "(https?://[^\\s]+)")
        if (!is.na(url_match[1, 1])) { endereco_eletronico <- url_match[1, 1] }
      }
    }
    
    if (!is.na(anexo)) {
      anexo <- str_remove_all(anexo, "\\s*\\d{1,2}:\\d{2}\\s*") %>% str_squish()
    }
    
    all_quotes_list[[length(all_quotes_list) + 1]] <- tibble::tibble(
      `Número da Pesquisa` = state_vars$numero_pesquisa, UASG = cotacao_uasg,  
      `Título da Pesquisa` = state_vars$titulo, Item = state_vars$item_num, CATMAT = state_vars$catmat,  
      `Descrição do Item` = state_vars$item_desc, `Nº Cotação` = n_cotacao, Inciso = inciso_val,  
      Nome = nome_completo, Quantidade = quantidade, Unidade = unidade,  
      `Preço unitário` = preco_formatado, Data = data_cotacao, Compõe = compone,  
      `Endereço Eletrônico` = endereco_eletronico, Anexo = anexo,
      LinhaIncompleta = linha_incompleta_flag
    )
  }
  return(all_quotes_list)
}

extract_format_C <- function(all_lines, state_vars) {
  all_quotes_list <- list()
  for (i in seq_along(all_lines)) {
    line <- all_lines[i]
    if (str_detect(line, "Cotação de preços para o item")) {
      fornecedor <- str_match(line, "Fornecedor: (.*?) - CNPJ:")[, 2]
      linha_inciso <- ""
      linha_financeira <- ""
      for (j in (i + 1):min(i + 10, length(all_lines))) {
        if (str_detect(all_lines[j], "^\\s*\\d+\\s+(I|II|III|IV|V)($|\\s)"))
          linha_inciso <- all_lines[j]
        if (str_detect(all_lines[j], "R\\$")) {
          linha_financeira <- all_lines[j]
          break
        }
      }
      if (nchar(linha_inciso) > 0 && nchar(linha_financeira) > 0) {
        n_cotacao <- str_match(linha_inciso, "^\\s*(\\d+)")[, 2]
        inciso <- str_match(linha_inciso, "^\\s*\\d+\\s+(I|II|III|IV|V)")[, 2]
        tokens_financeiro <- str_squish(linha_financeira) %>% str_split("\\s+") %>% .[[1]]
        quantidade <- tokens_financeiro[1]
        preco_unitario_str <- str_remove(tokens_financeiro[2], "R\\$")
        data_cotacao <- tokens_financeiro[3]
        compone <- tokens_financeiro[4]
        preco_numerico <- parse_br_number(preco_unitario_str)
        
        preco_formatado <- if (!is.na(preco_numerico)) {
          str_replace(sprintf("%.2f", preco_numerico), "\\.", ",")
        } else {
          preco_unitario_str
        }
        
        all_quotes_list[[length(all_quotes_list) + 1]] <- tibble::tibble(`Número da Pesquisa` = state_vars$numero_pesquisa, UASG = NA_character_, `Título da Pesquisa` = state_vars$titulo, Item = state_vars$item_num, CATMAT = state_vars$catmat, `Descrição do Item` = state_vars$item_desc, `Nº Cotação` = n_cotacao, Inciso = inciso, Nome = fornecedor, Quantidade = quantidade, Unidade = "", `Preço unitário` = preco_formatado, Data = data_cotacao, Compõe = compone, `Endereço Eletrônico` = NA_character_, Anexo = NA_character_, LinhaIncompleta = FALSE)
      }
    }
  }
  return(all_quotes_list)
}

process_pdf_data <- function(text_from_pages, progress_updater = NULL) {
  
  update_progress_if_possible <- function(value, detail) {
    if (!is.null(progress_updater)) {
      progress_updater(value = value, detail = detail)
    }
  }
  
  full_text <- paste(text_from_pages, collapse = "\n")
  all_lines <- unlist(str_split(full_text, "\n"))
  
  total_lines <- length(all_lines)
  
  final_quotes <- list()
  final_medians <- list()
  final_debug_info <- list()
  state_vars <- list(numero_pesquisa = NA, uasg = NA, titulo = NA, item_num = NA, catmat = NA, item_desc = NA)
  
  pesquisa_starts <- which(str_detect(all_lines, "Relatório de pesquisa de preço"))
  pesquisa_starts <- c(pesquisa_starts, length(all_lines) + 1)
  
  item_start_detector_regex <- "^\\s*Item:\\s*\\d+"
  total_item_blocks <- sum(str_detect(all_lines, item_start_detector_regex))
  
  for (p in 1:(length(pesquisa_starts) - 1)) {
    start_line <- pesquisa_starts[p]
    end_line <- pesquisa_starts[p + 1] - 1
    pesquisa_lines <- all_lines[start_line:end_line]
    
    header_idx <- which(str_detect(pesquisa_lines, "Número da Pesquisa\\s+UASG"))
    if (length(header_idx) > 0) {
      data_line <- pesquisa_lines[header_idx[1] + 1]
      parts <- str_squish(data_line) %>% str_split("\\s+") %>% .[[1]]
      if (length(parts) >= 2) {
        state_vars$numero_pesquisa <- parts[1]
        state_vars$uasg <- parts[2]
      }
    }
    
    titulo_idx <- which(str_detect(pesquisa_lines, "^\\s*Título:"))
    if (length(titulo_idx) > 0) {
      state_vars$titulo <- str_remove(pesquisa_lines[titulo_idx[1]], "Título:") %>% str_squish()
    }
    
    item_starts <- which(str_detect(pesquisa_lines, item_start_detector_regex))
    item_starts <- c(item_starts, length(pesquisa_lines) + 1)
    
    for (k in 1:(length(item_starts) - 1)) {
      item_start_line_local <- item_starts[k]
      item_end_line_local <- item_starts[k + 1] - 1
      item_lines <- pesquisa_lines[item_start_line_local:item_end_line_local]
      
      current_line_global <- start_line + item_start_line_local
      progress_value <- 0.99 * (current_line_global / total_lines)
      
      total_itens_na_pesquisa <- length(item_starts) - 1
      total_pesquisas <- length(pesquisa_starts) - 1
      detalhe_texto <- sprintf("Pesquisa %d/%d (Item %d/%d) | Total geral: %d itens",
                               p,
                               total_pesquisas,
                               k,
                               total_itens_na_pesquisa,
                               total_item_blocks)
      
      update_progress_if_possible(
        value = progress_value,
        detail = paste0(detalhe_texto, " (", round(progress_value * 100, 1), "%)")
      )
      
      state_vars$item_num <- str_extract(item_lines[1], "\\d+")
      
      desc_start_idx <- which(str_detect(item_lines, "Descrição do item"))
      desc_end_markers <- which(str_detect(item_lines, "Consolidação dos preços cotados|Nº\\s+Inciso\\s+Nome|Cotação de preços para o item"))
      
      desc_end_idx <- integer(0)
      if (length(desc_start_idx) > 0 && length(desc_end_markers) > 0) {
        valid_ends <- desc_end_markers[desc_end_markers > desc_start_idx[1]]
        if (length(valid_ends) > 0) {
          desc_end_idx <- min(valid_ends)
        }
      }
      
      if (length(desc_start_idx) > 0 && length(desc_end_idx) > 0 && desc_end_idx > (desc_start_idx[1])) {
        full_desc <- paste(item_lines[(desc_start_idx[1] + 1):(desc_end_idx[1] - 1)], collapse = " ") %>% str_squish()
        desc_matches <- str_match(full_desc, "^(\\d+)\\s*-\\s*(.*)")
        if (!is.na(desc_matches[1, 1])) {
          state_vars$catmat <- desc_matches[1, 2]
          state_vars$item_desc <- desc_matches[1, 3]
        } else {
          state_vars$catmat <- "N/A"
          state_vars$item_desc <- full_desc
        }
      }
      
      item_text <- paste(item_lines, collapse = "\n")
      if (str_detect(item_text, "Cotação de preços para o item")) {
        final_quotes <- c(final_quotes, extract_format_C(item_lines, state_vars))
      } else {
        final_quotes <- c(final_quotes, extract_format_AB(item_lines, state_vars))
      }
      
      median_value <- NA_real_
      header_line_idx <- which(str_detect(item_lines, "Menor Preço.*Média.*Mediana"))
      if (length(header_line_idx) > 0) {
        search_window <- item_lines[(header_line_idx[1] + 1):min(header_line_idx[1] + 5, length(item_lines))]
        for (line in search_window) {
          if (str_count(line, "R\\$") >= 3) {
            price_values <- str_extract_all(line, "R\\$\\s*[\\d.,]+")[[1]]
            if (length(price_values) >= 3) {
              median_value <- parse_br_number(price_values[3])
              break
            }
          }
        }
      }
      
      quantidade_painel <- NA_real_
      if (length(desc_start_idx) > 0 && length(desc_end_idx) > 0 && desc_end_idx > (desc_start_idx[1])) {
        search_window <- item_lines[(desc_start_idx[1] + 1):(desc_end_idx[1] - 1)]
        
        qty_header_idx <- which(str_detect(search_window, "Unidade de Fornecimento.*Quantidade"))
        if(length(qty_header_idx) > 0){
          data_line_idx <- qty_header_idx[1] + 1
          if(data_line_idx <= length(search_window)){
            data_line <- search_window[data_line_idx]
            qty_val <- str_extract_all(data_line, "[\\d.,]+")[[1]]
            if(length(qty_val) > 0){
              quantidade_painel <- parse_br_number(tail(qty_val, 1))
            }
          }
        }
        
        if(is.na(quantidade_painel)){
          unidade_line_idx <- which(str_detect(search_window, regex("Unidade", ignore_case = TRUE)))
          if (length(unidade_line_idx) > 0) {
            start_search <- unidade_line_idx[1]
            end_search <- min(start_search + 2, length(search_window))
            
            for (j in start_search:end_search) {
              line <- search_window[j]
              potential_qtys <- str_extract_all(line, "[\\d.,]+")[[1]]
              
              if (length(potential_qtys) > 0) {
                last_qty_str <- tail(potential_qtys, 1)
                parsed_num <- parse_br_number(last_qty_str)
                
                if (!is.na(parsed_num)) {
                  quantidade_painel <- parsed_num
                  break
                }
              }
            }
          }
        }
        
        if(is.na(quantidade_painel)){
          for (line in search_window) {
            line_cleaned <- str_squish(line)
            number_regex <- "[\\d.,]*\\d[\\d.,]*"
            qty_match <- str_match(line_cleaned, paste0("^(?:.*\\s)?(", number_regex, ")$"))
            if (!is.na(qty_match[1, 2])) {
              parsed_num <- parse_br_number(qty_match[1, 2])
              if (!is.na(parsed_num)) {
                quantidade_painel <- parsed_num
                break
              }
            }
          }
        }
      }
      
      metodo_calculo <- NA_character_
      regex_pattern <- regex("M.todo de c.lculo adotado:", ignore_case = TRUE)
      
      metodo_line_idx <- which(str_detect(item_lines, regex_pattern))
      if (length(metodo_line_idx) > 0) {
        metodo_line <- item_lines[metodo_line_idx[1]]
        metodo_match <- str_match(metodo_line, regex("M.todo de c.lculo adotado:\\s*(.+)", ignore_case = TRUE))
        
        if (!is.na(metodo_match[1, 2])) {
          captured_text <- str_trim(metodo_match[1, 2])
          text_no_spaces <- str_remove_all(captured_text, "\\s")
          
          if (str_detect(text_no_spaces, regex("Mediana", ignore_case = TRUE))) {
            metodo_calculo <- "Mediana"
          } else if (str_detect(text_no_spaces, regex("M.dia", ignore_case = TRUE))) {
            metodo_calculo <- "Média"
          } else {
            metodo_calculo <- captured_text
          }
        }
      }
      
      final_medians[[length(final_medians) + 1]] <- tibble::tibble(
        `Número da Pesquisa` = state_vars$numero_pesquisa,
        Item = as.integer(state_vars$item_num),
        `Mediana (PDF)` = median_value,
        `Quantidade (PDF)` = quantidade_painel,
        `Metodo Adotado (PDF)` = metodo_calculo
      )
      
      debug_text_block <- ""
      consolidation_start_idx <- which(str_detect(item_lines, regex("Consolida..o dos pre.os cotados", ignore_case=T)))
      if (length(consolidation_start_idx) > 0) {
        start_capture <- consolidation_start_idx[1]
        end_capture_idx <- which(str_detect(item_lines, regex("N. Cota..o|Nº\\s+Inciso\\s+Nome", ignore_case=T)))
        valid_ends <- end_capture_idx[end_capture_idx > start_capture]
        end_capture <- if (length(valid_ends) > 0) min(valid_ends) - 1 else start_capture + 6
        end_capture <- min(end_capture, length(item_lines))
        debug_text_block <- paste(item_lines[start_capture:end_capture], collapse = "\n")
      }
      
      final_debug_info[[length(final_debug_info) + 1]] <- tibble::tibble(
        Item = as.integer(state_vars$item_num),
        RawText = debug_text_block
      )
    }
  }
  
  quotes_df <- if (length(final_quotes) > 0)
    dplyr::distinct(dplyr::bind_rows(final_quotes))
  else
    data.frame()
  
  medians_df <- if (length(final_medians) > 0)
    dplyr::bind_rows(final_medians)
  else
    data.frame()
  
  debug_df <- if (length(final_debug_info) > 0)
    dplyr::bind_rows(final_debug_info)
  else
    data.frame()
  
  if (nrow(quotes_df) == 0) {
    stop("Nenhum dado de cotação válido foi extraído. Verifique se o PDF está no formato correto do compras.gov.br.")
  }
  
  return(list(quotes = quotes_df, medians = medians_df, item_count = total_item_blocks, debug_info = debug_df))
}


