# Função para preparar os dados da aba "Conferência"
prepare_analysis_data <- function(quotes_df, medians_df) {
  extracao_df <- quotes_df
  extracao_df$`Preço unitário` <- parse_br_number(extracao_df$`Preço unitário`)
  extracao_df <- extracao_df %>% mutate(Item = as.integer(Item))
  
  incisos_summary <- extracao_df %>%
    filter(Compõe == "Sim" & !is.na(`Preço unitário`) & !is.na(Inciso)) %>%
    group_by(`Número da Pesquisa`, Item) %>%
    summarise(
      INCISOS_CONCAT = paste(sort(unique(Inciso)), collapse = ","),
      .groups = "drop"
    )
  
  base_data <- extracao_df %>%
    filter(Compõe == "Sim" & !is.na(`Preço unitário`)) %>%
    group_by(`Número da Pesquisa`, Item) %>%
    arrange(as.integer(`Nº Cotação`)) %>%
    mutate(price_num = paste0("Preço ", row_number())) %>%
    summarise(
      CATMAT = first(CATMAT), `Descrição do Item` = first(`Descrição do Item`),
      prices_data = list(tibble::tibble(price_num, `Preço unitário`)), .groups = 'drop'
    ) %>%
    tidyr::unnest(prices_data) %>%
    tidyr::pivot_wider(names_from = price_num, values_from = `Preço unitário`) %>%
    ungroup()
  
  base_data$Item <- as.integer(base_data$Item)
  if (nrow(medians_df) > 0) {
    medians_df$Item <- as.integer(medians_df$Item)
  }
  
  dados_conferencia <- base_data %>%
    left_join(medians_df, by = c("Número da Pesquisa", "Item")) %>%
    left_join(incisos_summary, by = c("Número da Pesquisa", "Item")) %>%
    arrange(`Número da Pesquisa`, Item)
  
  price_cols <- grep("^Preço \\d+$", names(dados_conferencia), value = TRUE)
  
  if (length(price_cols) > 0) {
    nova_coluna_nome <- "A pesquisa atende o Parâmetro I ou II, Art.5º, da IN 65/2021?"
    nova_coluna_peso_nome <- "Proporção do Total"
    
    final_col_order <- c("Número da Pesquisa", "Item", "CATMAT", "Descrição do Item", price_cols,
                         "Média dos Preços", "Mediana dos Preços", "Desvio Padrão dos Preços",
                         "Coeficiente de Variação", "Usar Mediana?", "Mediana (PDF)",
                         "Método de Cálculo Adotado pelo Demandante",
                         "Valor de Referência", "Quantidade (PDF)", "Total Estimado",
                         nova_coluna_peso_nome,
                         "Valor unitário de referência = ou < que a mediana do Compras?",
                         nova_coluna_nome)
    
    num_data_rows <- nrow(dados_conferencia)
    total_row_excel_idx <- num_data_rows + 4 
    total_estimado_letter <- openxlsx::int2col(match("Total Estimado", final_col_order))
    total_cell_ref <- paste0("$", total_estimado_letter, "$", total_row_excel_idx)
    
    price_start_letter <- openxlsx::int2col(match(price_cols[1], final_col_order))
    price_end_letter <- openxlsx::int2col(match(price_cols[length(price_cols)], final_col_order))
    media_letter <- openxlsx::int2col(match("Média dos Preços", final_col_order))
    mediana_letter <- openxlsx::int2col(match("Mediana dos Preços", final_col_order))
    desvio_letter <- openxlsx::int2col(match("Desvio Padrão dos Preços", final_col_order))
    cv_letter <- openxlsx::int2col(match("Coeficiente de Variação", final_col_order))
    usar_mediana_letter <- openxlsx::int2col(match("Usar Mediana?", final_col_order))
    painel_letter <- openxlsx::int2col(match("Mediana (PDF)", final_col_order))
    ref_val_letter <- openxlsx::int2col(match("Valor de Referência", final_col_order))
    quantidade_painel_letter <- openxlsx::int2col(match("Quantidade (PDF)", final_col_order))
    metodo_demandante_letter <- openxlsx::int2col(match("Método de Cálculo Adotado pelo Demandante", final_col_order))
    
    dados_conferencia <- dados_conferencia %>%
      mutate(
        excel_row = row_number() + 2, 
        price_range = paste0(price_start_letter, excel_row, ":", price_end_letter, excel_row),
        `Média dos Preços` = paste0("ROUND(AVERAGE(", price_range, "),2)"),
        `Mediana dos Preços` = paste0("ROUND(MEDIAN(", price_range, "),2)"),
        `Desvio Padrão dos Preços` = paste0("STDEVP(", price_range, ")"),
        `Coeficiente de Variação` = paste0("IFERROR(", desvio_letter, excel_row, "/", media_letter, excel_row, ", 0)"),
        `Usar Mediana?` = paste0('IF(', cv_letter, excel_row, '>0.25, "Sim", "Não")'),
        `Valor de Referência` = paste0('IF(', metodo_demandante_letter, excel_row, '="Mediana", ', mediana_letter, excel_row, ', IF(', metodo_demandante_letter, excel_row, '="Menor Preço", MIN(', price_range, '), ', media_letter, excel_row, '))'),
        `Total Estimado` = paste0("IF(ISNUMBER(", quantidade_painel_letter, excel_row, "),", ref_val_letter, excel_row, "*", quantidade_painel_letter, excel_row, ',"-")'),
        !!nova_coluna_peso_nome := paste0("IFERROR(", total_estimado_letter, excel_row, "/", total_cell_ref, ", 0)"),
        !!nova_coluna_nome := dplyr::case_when(
          is.na(INCISOS_CONCAT) | INCISOS_CONCAT == "" ~ "Sem Inciso Coletado",
          stringr::str_detect(INCISOS_CONCAT, ",") ~ paste("Combinado - Parâmetros", INCISOS_CONCAT),
          INCISOS_CONCAT == "I" ~ "Parâmetro I",
          INCISOS_CONCAT == "II" ~ "Parâmetro II",
          INCISOS_CONCAT == "III" ~ "Parâmetro III",
          INCISOS_CONCAT == "IV" ~ "Parâmetro IV",
          INCISOS_CONCAT == "V" ~ "Parâmetro V",
          TRUE ~ ""
        ),
        `Valor unitário de referência = ou < que a mediana do Compras?` = paste0('IF(OR(ISBLANK(', ref_val_letter, excel_row, '), ISBLANK(', painel_letter, excel_row, ')), "Verificar", IF(', ref_val_letter, excel_row, '<=', painel_letter, excel_row, ', "Sim", "Não"))')
      )
    
    dados_conferencia <- dados_conferencia %>%
      rename(`Método de Cálculo Adotado pelo Demandante` = `Metodo Adotado (PDF)`)
    
    aba2_data <- dados_conferencia %>% select(any_of(final_col_order))
  } else {
    aba2_data <- dados_conferencia
  }
  
  return(aba2_data)
}

# Função para gerar o Workbook do Excel
generate_excel_workbook <- function(aba1_data, aba2_data, dicionario_df) {
  wb <- createWorkbook()
  
  # Estilos
  border_style <- createStyle(border = "TopBottomLeftRight", valign = "center", halign = "center")
  style_desc_item <- createStyle(border = "TopBottomLeftRight", valign = "center", halign = "left")
  header_style <- createStyle(textDecoration = "bold", fgFill = "#1E8449", fontColour = "white", halign = "center", valign = "center", border = "TopBottomLeftRight", wrapText = TRUE)
  style_alerta_final <- createStyle(fontColour = "#C00000", valign = "center")
  
  # --- Aba 1: Extração_PDF ---
  addWorksheet(wb, "Extração_PDF")
  
  urls_para_links <- NULL
  if ("Endereço Eletrônico" %in% names(aba1_data)) {
    urls_para_links <- str_extract(aba1_data$`Endereço Eletrônico`, "https?://[^\\s]+")
    aba1_data$`Endereço Eletrônico` <- ""
  }
  
  aba1_para_escrever <- aba1_data
  for (i in seq_len(nrow(aba1_para_escrever))) {
    if (isTRUE(aba1_para_escrever$LinhaIncompleta[i])) {
      aba1_para_escrever$`Número da Pesquisa`[i] <- paste(aba1_para_escrever$`Número da Pesquisa`[i], "\u2297")
    }
  }
  
  aba1_para_escrever <- aba1_para_escrever %>% select(-LinhaIncompleta)
  
  writeData(wb, "Extração_PDF", aba1_para_escrever, headerStyle = header_style)
  
  if (nrow(aba1_data) > 0) {
    addStyle(wb, "Extração_PDF", style = createStyle(border = "TopBottomLeftRight", valign = "center"), rows = 2:(nrow(aba1_data) + 1), cols = 1:ncol(aba1_para_escrever), gridExpand = TRUE, stack = TRUE)
    
    col_idx_pesquisa <- which(names(aba1_para_escrever) == "Número da Pesquisa")
    if (length(col_idx_pesquisa) > 0) {
      for (i in seq_len(nrow(aba1_data))) {
        if (isTRUE(aba1_data$LinhaIncompleta[i])) {
          addStyle(wb, "Extração_PDF", style = style_alerta_final, rows = i + 1, cols = col_idx_pesquisa, gridExpand = TRUE, stack = TRUE)
        }
      }
    }
  }
  
  if (!is.null(urls_para_links) && "Endereço Eletrônico" %in% names(aba1_para_escrever)) {
    col_idx <- which(names(aba1_para_escrever) == "Endereço Eletrônico")
    for (i in seq_along(urls_para_links)) {
      url <- urls_para_links[[i]]
      if (!is.na(url) && url != "") {
        link_obj <- url
        names(link_obj) <- url
        class(link_obj) <- "hyperlink"
        writeData(wb, sheet = "Extração_PDF", x = link_obj, startCol = col_idx, startRow = i + 1)
      }
    }
  }
  
  setColWidths(wb, "Extração_PDF", cols = 1:ncol(aba1_para_escrever), widths = "auto")
  setColWidths(wb, "Extração_PDF", cols = which(names(aba1_para_escrever) %in% c("Nome", "Descrição do Item", "Endereço Eletrônico", "Anexo")), widths = 50)
  setColWidths(wb, "Extração_PDF", cols = which(names(aba1_para_escrever) %in% c("Compõe", "CATMAT")), widths = 15)
  
  # --- Aba 2: Conferência ---
  addWorksheet(wb, "Conferência")
  
  if (nrow(aba2_data) > 0) {
    price_cols <- grep("^Preço \\d+$", names(aba2_data), value = TRUE)
    
    # Renomeia colunas para melhor visualização
    names(aba2_data)[names(aba2_data) == "Coeficiente de Variação"] <- "Coeficiente\nde Variação"
    names(aba2_data)[names(aba2_data) == "Mediana (PDF)"] <- "Mediana\n(compras.gov.br)"
    names(aba2_data)[names(aba2_data) == "Quantidade (PDF)"] <- "Quantidade\nSolicitada"
    names(aba2_data)[names(aba2_data) == "Método de Cálculo Adotado pelo Demandante"] <- "Método de Cálculo\nAdotado pelo Demandante"
    names(aba2_data)[names(aba2_data) == "A pesquisa atende o Parâmetro I ou II, Art.5º, da IN 65/2021?"] <- "A pesquisa atende o Parâmetro I ou II,\nArt.5º, da IN 65/2021?"
    names(aba2_data)[names(aba2_data) == "Valor unitário de referência = ou < que a mediana do Compras?"] <- "Valor unitário de referência\n= ou < que a mediana do compras.gov.br?"
    
    link_url <- "https://www.stj.jus.br/publicacaoinstitucional/index.php/MOP/issue/view/2096/showToc"
    friendly_text <- "Indicação: Usar média se o Coeficiente de Variação <=25%. (Fonte: STJ,2021)"
    excel_formula_link <- sprintf('=HYPERLINK("%s", "%s")', link_url, friendly_text)
    
    col_start_regra <- which(grepl("Desvio Padrão", names(aba2_data)))
    col_end_regra <- which(grepl("Usar Mediana", names(aba2_data)))
    if(length(col_start_regra) > 0 && length(col_end_regra) > 0) {
      writeFormula(wb, "Conferência", x = excel_formula_link, startCol = col_start_regra, startRow = 1)
      mergeCells(wb, "Conferência", cols = col_start_regra:col_end_regra, rows = 1)
      style_regra <- createStyle(halign = "center", textDecoration = "bold", fgFill = "#FCE4D6", border = "TopBottomLeftRight")
      addStyle(wb, "Conferência", style = style_regra, rows = 1, cols = col_start_regra:col_end_regra, gridExpand = TRUE)
    }
    
    header_style_aba2 <- createStyle(textDecoration = "bold", fgFill = "#D9E1F2", halign = "center", valign = "center", border = "TopBottomLeftRight", wrapText = TRUE)
    
    formula_cols <- c("Média dos Preços", "Mediana dos Preços", "Desvio Padrão dos Preços", "Coeficiente\nde Variação", "Usar Mediana?", "Valor de Referência", "Total Estimado", "Proporção do Total", "Valor unitário de referência\n= ou < que a mediana do compras.gov.br?")
    for(col in formula_cols) {
      if (col %in% names(aba2_data)) {
        class(aba2_data[[col]]) <- "formula"
      }
    }
    writeData(wb, "Conferência", aba2_data, startRow = 2, headerStyle = header_style_aba2, colNames = TRUE)
    
    addStyle(wb, "Conferência", style = border_style, rows = 3:(nrow(aba2_data) + 2), cols = 1:ncol(aba2_data), gridExpand = TRUE, stack = TRUE)
    
    col_idx_descricao <- which(names(aba2_data) == "Descrição do Item")
    if (length(col_idx_descricao) > 0) {
      addStyle(wb, "Conferência", style = style_desc_item, rows = 3:(nrow(aba2_data) + 2), cols = col_idx_descricao, gridExpand = TRUE, stack = TRUE)
    }
    
    currency_style <- createStyle(numFmt = "R$ #,##0.00")
    percent_style <- createStyle(numFmt = "0.00%")
    
    currency_cols_names <- c(price_cols, "Média dos Preços", "Mediana dos Preços", "Desvio Padrão dos Preços", "Valor de Referência", "Mediana\n(compras.gov.br)", "Total Estimado")
    percent_cols_names <- c("Coeficiente\nde Variação", "Proporção do Total")
    
    setColWidths(wb, "Conferência", cols = 1:ncol(aba2_data), widths = "auto")
    setColWidths(wb, "Conferência", cols = which(names(aba2_data) %in% c("Descrição do Item")), widths = 50)
    
    for(col_name in names(aba2_data)){
      col_idx <- which(names(aba2_data) == col_name)
      style_to_apply <- NULL
      if(col_name %in% currency_cols_names) {
        style_to_apply <- currency_style
      } else if (col_name %in% percent_cols_names) {
        style_to_apply <- percent_style
      }
      if(!is.null(style_to_apply)) addStyle(wb, "Conferência", style = style_to_apply, rows = 3:(nrow(aba2_data) + 2), cols = col_idx, gridExpand = TRUE, stack = TRUE)
    }
    
    if ("Total Estimado" %in% names(aba2_data)) {
      total_col_idx <- which(names(aba2_data) == "Total Estimado")
      if(length(total_col_idx) > 0) {
        label_col_idx <- total_col_idx - 1
        total_col_letter <- openxlsx::int2col(total_col_idx)
        sum_formula <- paste0("SUM(", total_col_letter, "3:", total_col_letter, nrow(aba2_data) + 2, ")")
        writeData(wb, "Conferência", x = "TOTAL GERAL:", startCol = label_col_idx, startRow = nrow(aba2_data) + 4)
        writeFormula(wb, "Conferência", x = sum_formula, startCol = total_col_idx, startRow = nrow(aba2_data) + 4)
        style_total_label <- createStyle(textDecoration = "bold", fgFill = "#D9E1F2", halign = "center", border = "TopBottomLeftRight")
        style_total_value <- createStyle(textDecoration = "bold", fgFill = "#D9E1F2", numFmt = "R$ #,##0.00", border = "TopBottomLeftRight", halign = "center")
        addStyle(wb, "Conferência", style = style_total_label, rows = nrow(aba2_data) + 4, cols = label_col_idx)
        addStyle(wb, "Conferência", style = style_total_value, rows = nrow(aba2_data) + 4, cols = total_col_idx)
      }
    }
  }
  
  # --- Aba 3: Dicionário ---
  addWorksheet(wb, "Dicionário de Variáveis")
  writeData(wb, "Dicionário de Variáveis", dicionario_df, headerStyle = header_style)
  style_desc_wrap <- createStyle(wrapText = TRUE, valign = "top", border = "TopBottomLeftRight")
  addStyle(wb, "Dicionário de Variáveis", style = createStyle(border = "TopBottomLeftRight", valign = "center"), rows = 2:(nrow(dicionario_df) + 1), cols = 1, gridExpand = TRUE, stack = TRUE)
  addStyle(wb, "Dicionário de Variáveis", style = style_desc_wrap, rows = 2:(nrow(dicionario_df) + 1), cols = 2, gridExpand = TRUE, stack = TRUE)
  header_row_style <- createStyle(textDecoration = "bold", fgFill = "#F2F2F2", border = "TopBottomLeftRight")
  header_rows <- which(startsWith(dicionario_df$Variável, "---"))
  for(row in header_rows) {
    addStyle(wb, "Dicionário de Variáveis", style = header_row_style, rows = row + 1, cols = 1:2, gridExpand = TRUE)
    mergeCells(wb, "Dicionário de Variáveis", cols = 1:2, rows = row + 1)
  }
  setColWidths(wb, "Dicionário de Variáveis", cols = 1, widths = 65)
  setColWidths(wb, "Dicionário de Variáveis", cols = 2, widths = 130)
  
  return(wb)
}
