      (function(){async function readPdfFile(file){if(!file||!window.pdfjsLib)return;if(window.Shiny&&Shiny.setInputValue){Shiny.setInputValue('pdf_text_pages',null,{priority:'event'});}try{const buf=await file.arrayBuffer();const loadingTask=window.pdfjsLib.getDocument({data:new Uint8Array(buf)});const pdf=await loadingTask.promise;const pages=[];for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p);const textContent=await page.getTextContent();const yTol=2;let lastY=-1;let lineBuffer=[];const pageLines=[];textContent.items.sort((a,b)=>{if(Math.abs(a.transform[5]-b.transform[5])>yTol){return b.transform[5]-a.transform[5];}return a.transform[4]-b.transform[4];});for(const item of textContent.items){if(lastY!==-1&&Math.abs(item.transform[5]-lastY)>yTol){pageLines.push(lineBuffer.join(' '));lineBuffer=[];}lineBuffer.push(item.str);lastY=item.transform[5];}if(lineBuffer.length>0){pageLines.push(lineBuffer.join(' '));}pages.push(pageLines.join('\\n'));}if(window.Shiny&&Shiny.setInputValue){Shiny.setInputValue('pdf_text_pages',pages,{priority:'event'});}}catch(err){console.error('Falha ao ler PDF via pdf.js:',err);if(window.Shiny&&Shiny.setInputValue){Shiny.setInputValue('pdf_text_pages_error',String(err),{priority:'event'});}}}document.addEventListener('change',e=>{const tgt=e.target;if(tgt&&tgt.id==='pdf_file'&&tgt.files&&tgt.files[0]){readPdfFile(tgt.files[0]);}},true);})();
    ")),
    
