# LÓGICA DO SERVIDOR (SERVER)
# ===================================================================================
server <- function(input, output, session) {
  
  log_text <- reactiveVal("Aguardando o upload do arquivo PDF...")
  processed_data_rv <- reactiveVal(NULL)
  debug_log_rv <- reactiveVal("Aguardando processamento para depuração...")
  excel_file_path_rv <- reactiveVal(NULL)
  
  # --- LÓGICA PARA NOVOS BOTÕES NO CABEÇALHO ---
  #observeEvent(input$about_us_button, {
   # showModal(modalDialog(
    #  title = "Sobre Nós",
     # p(""),
    #  p("A aplicação foi desenvolvida por Marcos Castaneda e Roney Melo, da Universidade Federal de Sergipe, com o objetivo de otimizar o processo de análise de pesquisas de preços."),
     # easyClose = TRUE,
      #footer = modalButton("Fechar")
  #  ))
  #})
  
 # output$download_manual_button <- downloadHandler(
  #  filename = function() {
   #   "Manual_da_Aplicacao.txt"
    #},
    #content = function(file) {
     # writeLines(c(
      #  "MANUAL DA APLICAÇÃO - ANÁLISE DE PREÇOS",
       # "",
        #"Este é um placeholder para o manual da aplicação."
    #  ), file)
    #}
  #)
  
  output$data_is_ready <- reactive({
    !is.null(processed_data_rv())
  })
  outputOptions(output, "data_is_ready", suspendWhenHidden = FALSE)
  
  observeEvent(input$pdf_file, {
    req(input$pdf_file)
    shinyjs::show("process_button_container")
    shinyjs::hide("reset_button_ui")
    log_text(paste0("Arquivo '", input$pdf_file$name, "' carregado.\nIniciando leitura do conteúdo no navegador... Aguarde."))
    processed_data_rv(NULL)
    excel_file_path_rv(NULL)
    debug_log_rv("Aguardando processamento para depuração...")
  })
  
  observeEvent(input$pdf_text_pages, {
    req(input$pdf_file$name)
    
    full_text <- paste(input$pdf_text_pages, collapse = "\n")
    
    if (stringr::str_detect(full_text, "Relatório de pesquisa de preço")) {
      log_text(paste0("Arquivo '", input$pdf_file$name, "' lido. Formato válido.\nPronto! Clique em processar para gerar a planilha Excel."))
      showNotification("✅ Formato de PDF reconhecido.", duration = 5, type = "message", closeButton = FALSE)
      shinyjs::enable("process_button")
    } else {
      log_text(paste0("Arquivo '", input$pdf_file$name, "' lido. Formato INVÁLIDO.\nPor favor, selecione um 'Relatório de pesquisa de preço' do Compras.gov.br."))
      showNotification("⚠️ Formato de PDF não reconhecido. Verifique o arquivo.", type = "warning", duration = 10)
      shinyjs::disable("process_button")
    }
  })
  
  observeEvent(input$pdf_text_pages_error, ignoreInit = TRUE, {
    log_text(paste(log_text(), "\n[AVISO] Falha do leitor PDF no navegador:", input$pdf_text_pages_error))
  })
  
  output$status_text <- renderText({ log_text() })
  
  output$process_button_ui <- renderUI({
    req(input$pdf_file)
    if (is.null(input$pdf_text_pages)) {
      actionButton("loading_button", "Lendo o PDF no navegador...", icon = icon("spinner", class = "fa-spin"), class = "btn-secondary btn-lg w-100", disabled = TRUE)
    } else {
      actionButton("process_button", "Processar e Baixar Planilha Excel", icon = icon("cogs"), class = "btn-primary btn-lg w-100")
    }
  })
  
  output$reset_button_ui <- renderUI({
    actionButton("reset_button", "Limpar e Recomeçar", icon = icon("eraser"), class = "btn-outline-danger w-100 mt-2")
  })
  
  shinyjs::hide("reset_button_ui")
  
  observeEvent(input$reset_button, {
    shinyjs::reset("pdf_file")
    shinyjs::hide("process_button_container")
    shinyjs::hide("reset_button_ui")
    shinyjs::runjs("document.getElementById('pdf_file').value = ''; Shiny.setInputValue('pdf_text_pages', null, {priority: 'event'});")
    processed_data_rv(NULL)
    excel_file_path_rv(NULL)
    log_text("Aguardando o upload do arquivo PDF...")
    debug_log_rv("Aguardando processamento para depuração...")
    updateTabsetPanel(session, "main_tabs", selected = "Início e Status")
  })
  
  observeEvent(input$process_button, {
    req(input$pdf_file, input$pdf_text_pages)
    
    dicionario_df <- tibble::tribble(
      ~Variável, ~Descrição,
      "--- ABA: Extração_PDF ---", "--- DADOS BRUTOS EXTRAÍDOS DIRETAMENTE DO RELATÓRIO PDF ---",
      "Número da Pesquisa", "Identificador único da pesquisa de preços no sistema Compras.gov.br.",
      "Item", "Número sequencial do item dentro da pesquisa de preços.",
      "Compõe", "Indica se a cotação foi considerada ('Sim') ou descartada ('Não') pelo demandante na composição do preço de referência.",
      "Nº Cotação", "Número sequencial da cotação para um determinado item.",
      "Parâmetro", "Inciso do Art. 5º da IN SEGES/ME nº 65/2021 que fundamenta a cotação (I, II, III, IV ou V).",
      "UASG", "Código da Unidade Administrativa de Serviços Gerais que realizou a cotação (relevante para Parâmetro I e II).",
      "Nome", "Nome do fornecedor ou da UASG adquirente do item (ex: nome da empresa, órgão público).",
      "Quantidade", "Quantidade do item cotado.",
      "Unidade", "Unidade de medida do item (ex: Unidade, Caixa, Peça).",
      "Preço unitário", "Valor monetário unitário da cotação.",
      "Data", "Data em que a cotação foi realizada ou coletada.",
      "Endereço Eletrônico", "URL do site onde a cotação foi obtida (relevante para Parâmetro III).",
      "Anexo", "Nome do arquivo anexado como comprovação da cotação (relevante para Parâmetros III, IV e V)",
      "CATMAT", "Código de identificação do item no Catálogo de Materiais do governo federal.",
      "Descrição do Item", "Descrição detalhada do material ou serviço pesquisado.",
      "Título da Pesquisa", "Título geral da pesquisa de preços, conforme cadastrado no sistema.",
      "--- ABA: Conferência ---", "--- DADOS CALCULADOS E CONSOLIDADOS PARA ANÁLISE E CONFERÊNCIA ---",
      "Preço 1, Preço 2, ...", "Colunas dinâmicas que apresentam os preços unitários das cotações válidas ('Compõe' = 'Sim') captadas no PDF.",
      "Média dos Preços", "Média aritmética de todos os preços válidos para o item. Fórmula: =MÉDIA(intervalo_de_preços).",
      "Mediana dos Preços", "Valor central dos preços válidos ordenados. Menos sensível a valores extremos. Fórmula: =MEDIAN(intervalo_de_preços).",
      "Desvio Padrão dos Preços", "Medida da dispersão dos preços em relação à média. Fórmula: =DESVPAD.P(intervalo_de_preços).",
      "Coeficiente de Variação", "Medida relativa da dispersão (Desvio Padrão / Média). Valores > 25% (0,25) indicam alta variabilidade dos preços.",
      "Usar Mediana?", "Sugestão automática. Indica 'Sim' se o Coeficiente de Variação for maior que 25%, sugerindo que a mediana é uma medida de referência mais robusta (Conforme indicação do STJ, 2021).",
      "Mediana (compras.gov.br)", "Valor da mediana extraído diretamente da seção 'Consolidação dos preços cotados' do PDF, para fins de comparação.",
      "Método de Cálculo Adotado pelo Demandante", "Método que o usuário declarou no sistema (Média, Mediana ou Menor Preço). Extraído do PDF.",
      "Valor de Referência", "Valor final calculado com base na escolha do 'Método de Cálculo Adotado pelo Demandante'.",
      "Quantidade Solicitada", "Quantidade total do item a ser adquirida, extraída do PDF.",
      "Total Estimado", "Valor total estimado para o item (Valor de Referência * Quantidade Solicitada).",
      "Proporção do Total", "Percentual que o 'Total Estimado' de um item representa em relação ao 'TOTAL GERAL' da planilha.",
      "Valor unitário de referência = ou < que a mediana do Compras?", "Verifica se o valor de referência do item é igual ou inferior à mediana calculada pelo painel de preços (Compras.gov.br).",
      "A pesquisa atende o Parâmetro I ou II, Art.5º, da IN 65/2021?", "Informa qual(is) parâmetro(s) foram utilizados na cotação, destacando o uso dos parâmetros preferenciais (I e II)."
    )
    
    shinyjs::hide("process_button_container")
    log_text("Iniciando o processo...\nIsso pode levar alguns segundos.\n\n--- LOG DE PROCESSAMENTO ---")
    
    withProgress(message = 'Em execução:', value = 0, {
      tmp_xlsx_path <- NULL
      process_success <- FALSE
      
      tryCatch({
        log_text(paste(log_text(), "\n[1/3] Extraindo dados do PDF..."))
        
        text_pages <- get_pdf_text_pages(NULL, input$pdf_text_pages)
        processed_data <- process_pdf_data(text_pages, progress_updater = setProgress)
        processed_data_rv(processed_data)
        
        if (!is.null(processed_data$debug_info) && nrow(processed_data$debug_info) > 0) {
          debug_output_str <- processed_data$debug_info %>%
            arrange(Item) %>%
            mutate(FormattedText = paste0("--- [DEBUG] Bloco de Texto para o Item: ", Item, " ---\n", RawText)) %>%
            pull(FormattedText) %>%
            paste(collapse = "\n\n")
          debug_log_rv(debug_output_str)
        }
        
        log_text(paste(log_text(), "\n[2/3] Preparando dados para análise e montagem do Excel..."))
        setProgress(0.95, detail = "Preparando dados para análise...")
        
        aba1_data <- processed_data$quotes %>%
          rename(Parâmetro = Inciso) %>%
          mutate(
            Item = as.integer(Item),
            `Nº Cotação` = as.integer(`Nº Cotação`),
            Anexo = ifelse(is.na(Anexo), "", Anexo)
          ) %>%
          arrange(`Número da Pesquisa`, Item, `Nº Cotação`) %>%
          select(any_of(c('Número da Pesquisa','Item', 'Compõe', 'Nº Cotação', 'Parâmetro', 'UASG','Nome', 'Quantidade', 'Unidade', 'Preço unitário', 'Data', 'Endereço Eletrônico', 'Anexo', 'CATMAT', 'Descrição do Item', 'Título da Pesquisa', "LinhaIncompleta")))
        
        aba2_data <- prepare_analysis_data(processed_data$quotes, processed_data$medians)
        
        log_text(paste(log_text(), "\n[3/3] Criando arquivo Excel..."))
        setProgress(0.99, detail = "Criando arquivo Excel...")
        
        wb <- generate_excel_workbook(aba1_data, aba2_data, dicionario_df)
        
        tmp_xlsx_path <- tempfile(fileext = ".xlsx")
        saveWorkbook(wb, tmp_xlsx_path, overwrite = TRUE)
        excel_file_path_rv(tmp_xlsx_path)
        
        filename <- paste0("Análise_Pesquisa_", tools::file_path_sans_ext(input$pdf_file$name), format(Sys.time(), "_%d-%m-%Y_%Hh%Mm%Ss"), ".xlsx")
        file_data <- readBin(tmp_xlsx_path, "raw", file.info(tmp_xlsx_path)$size)
        encoded_data <- base64enc::base64encode(file_data)
        
        session$sendCustomMessage(type = "download_b64", message = list(data = encoded_data, filename = filename, mime = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))
        
        log_text(paste(log_text(), "\nSucesso! O download foi iniciado."))
        process_success <- TRUE
        updateTabsetPanel(session, "main_tabs", selected = "Resumo da Extração")
        
      }, error = function(e) {
        log_text(paste(log_text(), "\n\n--- ERRO DURANTE O PROCESSAMENTO ---\n", e$message))
        processed_data_rv(NULL)
        excel_file_path_rv(NULL)
        
        error_title <- "Ocorreu um Erro Inesperado"
        error_message <- "Ocorreu um erro durante o processamento. Verifique o log de status para detalhes técnicos."
        
        if (grepl("Nenhum dado de cotação válido foi extraído", e$message, ignore.case = TRUE)) {
          error_title <- "Formato de PDF Inválido"
          error_message <- "Não foi possível extrair os dados. A aplicação funciona exclusivamente com o PDF de 'Relatório de pesquisa de preço' gerado pelo sistema Compras.gov.br."
        }
        
        showModal(modalDialog(
          title = tagList(icon("times-circle", class="text-danger"), " ", error_title),
          error_message,
          footer = modalButton("Fechar"),
          easyClose = TRUE
        ))
      }, finally = {
        if (process_success) {
          shinyjs::show("reset_button_ui")
        } else {
          shinyjs::show("process_button_container")
        }
      })
    })
  })
  
  output$summary_cards_ui <- renderUI({
    data <- processed_data_rv()
    req(data, cancelOutput = TRUE)
    
    selected_research <- input$summary_selected_research
    quotes_df <- data$quotes
    item_count <- data$item_count
    
    if (!is.null(selected_research) && selected_research != "" && selected_research != "all") {
      quotes_df <- quotes_df %>% filter(`Número da Pesquisa` == selected_research)
      item_count <- length(unique(quotes_df$Item))
    }
    
    req(nrow(quotes_df) > 0)
    
    total_quotes <- nrow(quotes_df)
    total_searches <- length(unique(quotes_df$`Número da Pesquisa`))
    
    card_height <- "83px"
    
    bslib::layout_columns(
      col_widths = c(4, 4, 4),
      bslib::value_box(
        title = "Total de Pesquisas",
        value = total_searches,
        showcase = icon("file-invoice"),
        theme = value_box_theme(bg = "#1E8449", fg = "white"),
        height = card_height,
        class = "vertically-centered-card"
      ),
      bslib::value_box(
        title = "Total de Itens",
        value = item_count,
        showcase = icon("tag"),
        theme = value_box_theme(bg = "#1E8449", fg = "white"),
        height = card_height,
        class = "vertically-centered-card"
      ),
      bslib::value_box(
        title = "Total de Cotações",
        value = total_quotes,
        showcase = icon("hand-holding-usd"),
        theme = value_box_theme(bg = "#1E8449", fg = "white"),
        height = card_height,
        class = "vertically-centered-card"
      )
    )
  })
  
  output$summary_details_output <- renderText({
    data <- processed_data_rv()
    req(data, cancelOutput = TRUE)
    
    original_quotes_df <- data$quotes
    req(nrow(original_quotes_df) > 0)
    
    selected_research_val <- input$summary_selected_research
    
    quotes_to_process <- if (!is.null(selected_research_val) && selected_research_val != "all" && selected_research_val != "") {
      original_quotes_df %>% filter(`Número da Pesquisa` == selected_research_val)
    } else {
      original_quotes_df
    }
    
    pesquisas_str <- if (!is.null(selected_research_val) && selected_research_val != "all" && selected_research_val != "") {
      selected_research_val
    } else {
      paste(unique(original_quotes_df$`Número da Pesquisa`), collapse = ", ")
    }
    
    incisos_por_item <- quotes_to_process %>%
      filter(Compõe == "Sim" & !is.na(parse_br_number(`Preço unitário`)) & !is.na(Inciso)) %>%
      group_by(`Número da Pesquisa`, Item) %>%
      summarise(INCISOS_CONCAT = paste(sort(unique(Inciso)), collapse = ","), .groups = 'drop')
    
    count_I           <- sum(incisos_por_item$INCISOS_CONCAT == "I")
    count_II          <- sum(incisos_por_item$INCISOS_CONCAT == "II")
    count_III         <- sum(incisos_por_item$INCISOS_CONCAT == "III")
    count_IV          <- sum(incisos_por_item$INCISOS_CONCAT == "IV")
    count_V           <- sum(incisos_por_item$INCISOS_CONCAT == "V")
    count_combinados  <- sum(stringr::str_detect(incisos_por_item$INCISOS_CONCAT, ","))
    
    items_less_than_3_quotes <- quotes_to_process %>%
      filter(Compõe == "Sim" & !is.na(parse_br_number(`Preço unitário`))) %>%
      group_by(`Número da Pesquisa`, Item) %>%
      summarise(n_quotes = n(), .groups = 'drop') %>%
      filter(n_quotes < 3) %>%
      nrow()
    
    unproven_quotes_count <- quotes_to_process %>%
      filter(
        Inciso %in% c("III", "IV", "V"),
        (is.na(`Endereço Eletrônico`) | str_trim(`Endereço Eletrônico`) == "") &
          (is.na(Anexo) | str_trim(Anexo) == "")
      ) %>%
      nrow()
    
    total_itens_pool_III_IV_V <- incisos_por_item %>%
      filter(str_detect(INCISOS_CONCAT, "III|IV|V")) %>%
      nrow()
    
    details_text <- paste(
      paste("Arquivo Processado:", input$pdf_file$name),
      "------------------------------------",
      paste("Números das Pesquisas:", pesquisas_str),
      "------------------------------------",
      "Parâmetros utilizados nas pesquisas de preços (contagem de itens):",
      sprintf("I   – Compras.gov.br: %d", count_I),
      sprintf("II  – Contratações similares: %d", count_II),
      sprintf("III – Sites Especializados: %d", count_III),
      sprintf("IV  – Fornecedor: %d", count_IV),
      sprintf("V   – Notas Fiscais: %d", count_V),
      sprintf("Parâmetros Combinados: %d", count_combinados),
      "------------------------------------",
      "Observação:",
      sprintf("- Foram encontrados %d itens com menos de 3 cotações válidas.", items_less_than_3_quotes),
      sprintf("- Dentre os %d itens que utilizaram os parâmetros III, IV ou V, foram encontradas %d cotações sem a devida comprovação (endereço eletrônico e/ou anexo).", total_itens_pool_III_IV_V, unproven_quotes_count),
      sep = "\n"
    )
    
    integrity_text <- ""
    
    if (!is.null(selected_research_val) && nzchar(selected_research_val)) {
      check_result <- ""
      if (selected_research_val == "all") {
        all_researches <- unique(original_quotes_df$`Número da Pesquisa`)
        failed_researches <- c()
        
        for(current_research in all_researches) {
          pesquisa_quotes <- original_quotes_df %>%
            filter(`Número da Pesquisa` == current_research) %>%
            mutate(Item = as.integer(Item), `Nº Cotação` = as.integer(`Nº Cotação`))
          
          unique_items <- sort(unique(pesquisa_quotes$Item))
          
          research_has_failure <- FALSE
          for (current_item in unique_items) {
            item_quote_numbers <- pesquisa_quotes %>%
              filter(Item == current_item) %>%
              pull(`Nº Cotação`) %>%
              unique() %>%
              sort()
            
            if (length(item_quote_numbers) >= 2) {
              min_q <- min(item_quote_numbers, na.rm = TRUE)
              max_q <- max(item_quote_numbers, na.rm = TRUE)
              
              expected_seq <- seq(from = min_q, to = max_q)
              missing_quotes <- setdiff(expected_seq, item_quote_numbers)
              
              if (length(missing_quotes) > 0) {
                failed_researches <- c(failed_researches, current_research)
                research_has_failure <- TRUE
                break
              }
            }
          }
          if (research_has_failure) next
        }
        
        if (length(failed_researches) == 0) {
          total_items <- data$item_count
          check_result <- paste0("✅ Sucesso! Todas as cotações listadas para os ", total_items, " itens dessa pesquisa foram coletadas.")
        } else {
          failed_list <- paste(unique(failed_researches), collapse = ", ")
          check_result <- paste0("⚠️ Atenção! As seguintes pesquisas apresentaram falhas na sequência de cotações: ", failed_list, ". Para ver os detalhes, selecione cada pesquisa individualmente no menu acima.")
        }
        
      } else {
        pesquisa_quotes <- original_quotes_df %>%
          filter(`Número da Pesquisa` == selected_research_val) %>%
          mutate(Item = as.integer(Item), `Nº Cotação` = as.integer(`Nº Cotação`))
        
        if (nrow(pesquisa_quotes) == 0) {
          check_result <- paste("Nenhuma cotação encontrada para a pesquisa", selected_research_val)
        } else {
          unique_items <- sort(unique(pesquisa_quotes$Item))
          failed_items <- c()
          
          for (current_item in unique_items) {
            item_quote_numbers <- pesquisa_quotes %>%
              filter(Item == current_item) %>%
              pull(`Nº Cotação`) %>%
              unique() %>%
              sort()
            
            if (length(item_quote_numbers) >= 2) {
              min_q <- min(item_quote_numbers, na.rm = TRUE)
              max_q <- max(item_quote_numbers, na.rm = TRUE)
              
              expected_seq <- seq(from = min_q, to = max_q)
              missing_quotes <- setdiff(expected_seq, item_quote_numbers)
              
              if (length(missing_quotes) > 0) {
                failed_items <- c(failed_items, current_item)
              }
            }
          }
          
          if (length(failed_items) == 0) {
            total_items <- length(unique_items)
            check_result <- paste0("✅ Sucesso! Todas as cotações listadas para os ", total_items, " itens dessa pesquisa foram coletadas.")
          } else {
            if (length(failed_items) > 1) {
              failed_items_str <- paste(paste(head(failed_items, -1), collapse = ", "), "e", tail(failed_items, 1))
            } else {
              failed_items_str <- as.character(failed_items)
            }
            check_result <- paste0("⚠️ Atenção! Os itens ", failed_items_str, " não tiveram todas as suas cotações coletadas.")
          }
        }
      }
      
      integrity_text <- paste(
        "------------------------------------",
        "Verificação de Integridade:",
        check_result,
        sep="\n"
      )
    }
    
    paste(details_text, integrity_text, sep = "\n")
  })
  
